/**
 * Read-only, full-inventory integration parity test.
 * The snapshot is generated by the existing training-ready gate, not fabricated
 * as a Rust authority. This never reads, modifies, or publishes buyer records.
 */
import assert from "node:assert/strict";
import fs from "node:fs";
import { filterTrainingResources, type ResourceFilters, type ResourceListing } from "../src/lib/resource-catalog";

const file = process.env.SOCTHINK_CATALOG_SNAPSHOT;
const base = process.env.SOCTHINK_RUST_CATALOG_TEST_URL;
if (!file || !base || !/^http:\/\/127\.0\.0\.1:\d+$/.test(base)) {
  throw new Error("Requires a local snapshot and loopback-only Rust test URL");
}
const snapshot = JSON.parse(fs.readFileSync(file,"utf8")) as {
  version:number; generatedAt:string; rows:ResourceListing[];
};
assert.equal(snapshot.version,1);
assert.ok(snapshot.rows.length>0);
assert.deepEqual([...new Set(snapshot.rows.map(row=>row.id))].length,snapshot.rows.length);

const cases:ResourceFilters[]=[
  {},{query:"AMC"},{query:"袋鼠"},{query:"2024"},{query:"2023"},
  {query:"none-this-random-string-907124"},
  ...[...new Set(snapshot.rows.map(x=>x.competition))].map(competition=>({competition})),
  ...[...new Set(snapshot.rows.map(x=>x.gradeBand))].filter((x):x is string=>Boolean(x)).map(gradeBand=>({gradeBand})),
  ...[...new Set(snapshot.rows.map(x=>x.paperType))].map(paperType=>({paperType})),
];
for(const row of snapshot.rows.filter((_,index)=>index%Math.max(1,Math.floor(snapshot.rows.length/28))===0).slice(0,29)){
  cases.push({query:row.id},{competition:row.competition,gradeBand:row.gradeBand||undefined,paperType:row.paperType});
}
async function main(){
let tested=0;
for(const filters of cases){
  const expected=filterTrainingResources(snapshot.rows,filters);
  const actual:ResourceListing[]=[];
  let offset=0;
  do{
    const params=new URLSearchParams({limit:"91",offset:String(offset)});
    for(const key of ["query","competition","gradeBand","paperType"] as const){
      const value=filters[key];
      if(value)params.set(key,value);
    }
    const response=await fetch(base+"/v1/catalog/resources?"+params);
    assert.equal(response.status,200);
    const payload=await response.json() as {
      total:number;offset:number;limit:number;hasMore:boolean;items:ResourceListing[];
    };
    assert.equal(payload.total,expected.length,"Total mismatch for "+JSON.stringify(filters));
    assert.equal(payload.offset,offset);
    assert.equal(payload.limit,91);
    actual.push(...payload.items);
    offset+=payload.items.length;
    assert.equal(payload.hasMore,offset<payload.total);
    if(payload.hasMore)assert.ok(payload.items.length,"Pagination must make progress");
  }while(offset<expected.length);
  assert.deepEqual(actual,expected,"Full inventory mismatch for "+JSON.stringify(filters));
  tested++;
}
console.log("RUST_REAL_INVENTORY_PARITY=PASS rows="+snapshot.rows.length+" filterCases="+tested);

}
main().catch(err=>{console.error(err);process.exitCode=1});
